// Run from the repository root: node docs/scripts/generate-brand.mjs
// Requires docs dependencies. Desktop PNG/ICNS/ICO files are generated by
// desktop/scripts/prepare.mjs from desktop/icon.svg during app builds.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import sharp from 'sharp';

const root = new URL('../../', import.meta.url);
const mark = await readFile(new URL('docs/public/brand/kikimimi-mark.svg', root), 'utf8');
const white = mark.replace('fill="#191b1d"', 'fill="#ffffff"');
const icon = white.replace('viewBox=', 'width="512" height="512" viewBox=')
  .replace('  <!-- Ear outline', '  <rect x="200" y="200" width="1200" height="1200" rx="264" fill="#191b1d"/>\n  <!-- Ear outline');
for (const [path, contents] of [
  ['docs/public/brand/kikimimi-mark-white.svg', white],
  ['docs/public/brand/kikimimi-icon.svg', icon],
  ['docs/public/favicon.svg', icon],
  ['web/src/assets/kikimimi-icon.svg', icon],
  ['desktop/icon.svg', icon],
  ['desktop/ui/brand.svg', icon],
]) {
  const target = new URL(path, root);
  await mkdir(new URL('.', target), { recursive: true });
  await writeFile(target, contents);
}
// Raw RGBA avoids adding a runtime image decoder to the desktop app.
const tray = await sharp(Buffer.from(mark)).resize(36, 36).ensureAlpha().raw().toBuffer();
await writeFile(new URL('desktop/tray.rgba', root), tray);
console.log('Updated web, docs, desktop, and menu bar branding.');
